  // ---------- Задания 1–3. Небольшие тексты ----------
  add("r0-1", [
    { t: "input", ctx: "c", q: "Самостоятельно подбери вводное сочетание со значением радости, удачи, которое должно стоять на месте пропуска в предложении 4. Запиши его.", a: ["к счастью", "по счастью", "к радости", "к всеобщей радости"], e: "Предложение 4 сообщает о хорошем исходе: «К счастью, мальчик выжил»." },
    { t: "multi", open: true, ctx: "c", q: "Отметь верные характеристики фрагмента текста.", o: ["В предложении 2 союз «и» соединяет части сложного предложения.", "Предложение 3 — сложноподчинённое с придаточной определительной частью.", "В предложении 1 есть деепричастный оборот.", "Предложения 4 и 5 связаны с помощью наречия «так».", "Текст написан в официально-деловом стиле.", "В предложении 5 есть причастный оборот."], a: [0, 1, 3], e: "«…считалось неизлечимым, и спасти… не мог» — две части с «и»; «вакцину, которую…» — придаточное определительное; «Так началась…» связывает 5-е предложение с 4-м. Деепричастного и причастного оборотов нет, стиль не деловой." },
    { t: "input", ctx: "c", q: "Прочитай фрагмент словарной статьи. Определи, в каком значении слово ИСТОРИЯ употреблено в предложении 5, и запиши цифру.\n\nИСТОРИЯ, -и, ж.\n1. Последовательный ход развития чего-либо. История языка. История науки.\n2. Наука, изучающая прошлое человечества. Учебник истории.\n3. Происшествие, случай. Со мной произошла забавная история.\n4. Медицинский документ с записями о болезни пациента. Заполнить историю болезни.", a: ["1"], e: "«Началась история прививки» — начался ход её развития. Это значение 1." },
    { t: "input", ctx: "d", q: "Самостоятельно подбери наречие со значением следствия, которое должно стоять на месте пропуска в предложении 4. Запиши его.", a: ["поэтому", "потому", "оттого"], e: "Предложение 4 — следствие из предложения 3: шерсть защищает от мороза, поэтому лошади переносят холод." },
    { t: "multi", open: true, ctx: "d", q: "Отметь верные характеристики фрагмента текста.", o: ["В предложении 2 есть деепричастный оборот.", "Предложения 1 и 2 связаны с помощью личного местоимения «она».", "В предложении 3 есть причастный оборот.", "Предложение 5 — сложносочинённое.", "Текст относится к разговорному стилю.", "В предложении 4 есть однородные члены предложения."], a: [0, 1, 3], e: "«разгребая его копытами» — деепричастный оборот; «Она» заменяет слова «якутская лошадь»; в предложении 5 две основы с «и». Причастного оборота и однородных членов в названных предложениях нет." },
    { t: "input", ctx: "d", q: "Прочитай фрагмент словарной статьи. Определи, в каком значении слово ДОБЫВАТЬ употреблено в предложении 2, и запиши цифру.\n\nДОБЫВАТЬ, -аю, -аешь; несов.\n1. Доставать, приобретать с трудом, усилиями. Добывать пропитание. Добывать сведения.\n2. Извлекать из недр земли. Добывать алмазы, нефть.\n3. Получать в результате каких-либо действий. Добывать огонь трением.", a: ["1"], e: "Лошадь с трудом достаёт корм из-под снега — значение 1." },
    { t: "input", ctx: "e", q: "Самостоятельно подбери притяжательное местоимение, которое должно стоять на месте пропуска в предложении 5. Запиши его.", a: ["его"], e: "Речь об учениках Боткина: «Его ученики стали известными врачами и профессорами»." },
    { t: "multi", open: true, ctx: "e", q: "Отметь верные характеристики фрагмента текста.", o: ["Предложения 3 и 4 связаны с помощью личного местоимения «он».", "Предложение 2 — сложное, в нём есть придаточная изъяснительная часть.", "В предложении 3 есть придаточная определительная часть.", "В предложении 1 есть однородные члены предложения.", "В предложении 6 есть причастный оборот.", "Слово «ведь» в предложении 2 — вводное."], a: [0, 1, 2], e: "«Он создал…», «учил, что врач должен…», «желтухи, которую позже назвали…» — верно. Однородных членов в предложении 1 и причастного оборота в предложении 6 нет; «ведь» — союз, а не вводное слово." },
    { t: "input", ctx: "e", q: "Прочитай фрагмент словарной статьи. Определи, в каком значении слово ШКОЛА употреблено в предложении 4, и запиши цифру.\n\nШКОЛА, -ы, ж.\n1. Учебное заведение, обычно для общего образования. Ходить в школу.\n2. Выучка, опыт. Пройти суровую школу жизни.\n3. Направление в науке или искусстве, связанное с именем учёного или художника, а также его последователи. Научная школа академика Павлова.\n4. Здание, в котором находится учебное заведение. Новая школа на окраине.", a: ["3"], e: "«Создал научную школу» — направление в науке и круг учеников. Это значение 3." },
    { t: "input", ctx: "f", q: "Самостоятельно подбери указательное местоимение, которое должно стоять на месте пропуска в предложении 4. Запиши его.", a: ["этот"], e: "Местоимение указывает на Ленские столбы, о которых говорилось раньше: «Этот уникальный памятник природы…»." },
    { t: "multi", open: true, ctx: "f", q: "Отметь верные характеристики фрагмента текста.", o: ["Предложения 2 и 3 связаны с помощью личного местоимения «они».", "В предложении 3 есть однородные подлежащие.", "Предложение 3 — сложноподчинённое.", "В предложении 5 есть обособленное обстоятельство.", "Текст относится к художественному стилю.", "В предложении 1 есть сравнительный оборот."], a: [0, 1, 2], e: "«Они» заменяет слово «скалы»; «ветер, вода и мороз» — однородные подлежащие придаточной части с «который». Обособлений в предложении 5 и сравнительного оборота в предложении 1 нет, стиль не художественный." },
    { t: "input", ctx: "f", q: "Прочитай фрагмент словарной статьи. Определи, в каком значении слово ПАМЯТНИК употреблено в предложении 4, и запиши цифру.\n\nПАМЯТНИК, -а, м.\n1. Скульптурное или архитектурное сооружение в честь кого-либо или чего-либо. Памятник Пушкину.\n2. Надгробное сооружение.\n3. Объект, ценный для истории, культуры или природы и охраняемый за эту ценность. Памятник древнерусской письменности. Памятник природы.\n4. перен. То, что служит свидетельством чего-либо. Эта книга — памятник эпохи.", a: ["3"], e: "«Памятник природы» — охраняемый природный объект. Это значение 3." }
  ], {
    c: "(1) Летом 1885 года к Луи Пастеру привезли девятилетнего мальчика, которого покусала бешеная собака. (2) В то время бешенство считалось неизлечимым, и спасти укушенного не мог ни один врач. (3) Пастер решился ввести мальчику вакцину, которую до этого испытывал только на животных. (4) <…>, мальчик выжил, и вскоре к учёному стали приезжать больные из разных стран. (5) Так началась история прививки от бешенства, которая спасла тысячи жизней.",
    d: "(1) Якутская лошадь — одна из самых выносливых пород в мире. (2) Она круглый год живёт под открытым небом и зимой сама добывает корм из-под снега, разгребая его копытами. (3) Длинная густая шерсть надёжно защищает её от мороза. (4) <…> якутские лошади спокойно переносят холод ниже пятидесяти градусов. (5) Эту породу ценят за неприхотливость, и в Якутии её разводят до сих пор.",
    e: "(1) Сергей Петрович Боткин — один из основоположников научной клинической медицины в России. (2) Он учил, что врач должен изучать каждого больного, ведь у разных людей одна и та же болезнь протекает по-разному. (3) Боткин первым описал инфекционную природу желтухи, которую позже назвали болезнью Боткина. (4) Он создал крупную научную школу. (5) <…> ученики стали известными врачами и профессорами. (6) Сегодня именем Боткина названа одна из крупнейших больниц Москвы.",
    f: "(1) Ленские столбы — природный парк на правом берегу Лены, выше Якутска по течению. (2) Причудливые скалы тянутся вдоль реки на десятки километров. (3) Они образовались из известняка, который миллионы лет разрушали ветер, вода и мороз. (4) <…> уникальный памятник природы в 2012 году включили в список Всемирного наследия ЮНЕСКО. (5) Каждое лето сюда приезжают туристы со всей России."
  });

